// Global state stored in flow context
let state = flow.get('greenhouse_state') || {
    autoMode: true,
    moistureAMin: 35.0,
    moistureAMax: 45.0,
    moistureBMin: 35.0,
    moistureBMax: 45.0,
    tempHigh: 32.0,
    tempLow: 30.0,
    lightMin: 30.0,
    lightMax: 40.0,
    valves: { bed_a: 0, bed_b: 0 },
    pump: 0,
    fan: 0,
    light: 0,
    waterLow: false
};

const topic = msg.topic;
const data = msg.payload;
const parts = topic.split('/');
const nodeId = parts[1];

let commandMessages = [];

// Check if water is low from utility node (Digital: 1 = Low Water)
if (nodeId === 'utility') {
    state.waterLow = (data.digital === 1);
    if (state.waterLow) {
        // EMERGENCY SHUTDOWN (Section 8)
        state.pump = 0;
        state.valves.bed_a = 0;
        state.valves.bed_b = 0;

        commandMessages.push({
            topic: 'greenhouse/actuator/pump/command',
            payload: { command: 'SET_COIL', coil: 0, emergency: true }
        });
        commandMessages.push({
            topic: 'greenhouse/bed_a/command',
            payload: { command_id: Date.now(), output: 0 }
        });
        commandMessages.push({
            topic: 'greenhouse/bed_b/command',
            payload: { command_id: Date.now(), output: 0 }
        });
        commandMessages.push({
            topic: 'greenhouse/alerts',
            payload: {
                level: 'DANGER',
                source: 'utility',
                message: '🚨 น้ำในถังต่ำ! หยุดปั๊มน้ำและปิดวาล์ว A/B ทั้งหมดทันที'
            }
        });

        flow.set('greenhouse_state', state);
        return [commandMessages];
    }
}

// If not in AutoMode, skip automatic threshold decisions
if (!state.autoMode) {
    flow.set('greenhouse_state', state);
    return [commandMessages];
}

// Bed A Moisture Rule
if (nodeId === 'bed_a') {
    const moisture = data.analog;
    const potPresent = (data.digital === 1);

    if (moisture < state.moistureAMin && potPresent && state.valves.bed_a === 0 && !state.waterLow) {
        state.valves.bed_a = 1;
        commandMessages.push({
            topic: 'greenhouse/bed_a/command',
            payload: { command_id: Date.now(), output: 1 }
        });
    } else if ((moisture > state.moistureAMax || !potPresent) && state.valves.bed_a === 1) {
        state.valves.bed_a = 0;
        commandMessages.push({
            topic: 'greenhouse/bed_a/command',
            payload: { command_id: Date.now(), output: 0 }
        });
    }
}

// Bed B Moisture Rule
if (nodeId === 'bed_b') {
    const moisture = data.analog;
    const potPresent = (data.digital === 1);

    if (moisture < state.moistureBMin && potPresent && state.valves.bed_b === 0 && !state.waterLow) {
        state.valves.bed_b = 1;
        commandMessages.push({
            topic: 'greenhouse/bed_b/command',
            payload: { command_id: Date.now(), output: 1 }
        });
    } else if ((moisture > state.moistureBMax || !potPresent) && state.valves.bed_b === 1) {
        state.valves.bed_b = 0;
        commandMessages.push({
            topic: 'greenhouse/bed_b/command',
            payload: { command_id: Date.now(), output: 0 }
        });
    }
}

// Pump Coordination Rule: Any valve open & water not low -> Pump ON; No valve open -> Pump OFF
const anyValveOpen = (state.valves.bed_a === 1 || state.valves.bed_b === 1);
if (anyValveOpen && !state.waterLow && state.pump === 0) {
    state.pump = 1;
    commandMessages.push({
        topic: 'greenhouse/actuator/pump/command',
        payload: { command: 'SET_COIL', coil: 1 }
    });
} else if (!anyValveOpen && state.pump === 1) {
    state.pump = 0;
    commandMessages.push({
        topic: 'greenhouse/actuator/pump/command',
        payload: { command: 'SET_COIL', coil: 0 }
    });
}

// Climate Fan Temperature Rule: > 32°C -> ON; < 30°C -> OFF; Digital 1 = Fan Request
if (nodeId === 'climate') {
    const temp = data.analog;
    const fanReq = (data.digital === 1);
    if (fanReq) {
        if (state.fan === 0) {
            state.fan = 1;
            commandMessages.push({
                topic: 'greenhouse/actuator/fan/command',
                payload: { command: 'SET_COIL', coil: 1 }
            });
            commandMessages.push({
                topic: 'greenhouse/climate/command',
                payload: { command_id: Date.now(), output: 1 }
            });
        }
    } else if (temp > state.tempHigh && state.fan === 0) {
        state.fan = 1;
        commandMessages.push({
            topic: 'greenhouse/actuator/fan/command',
            payload: { command: 'SET_COIL', coil: 1 }
        });
        commandMessages.push({
            topic: 'greenhouse/climate/command',
            payload: { command_id: Date.now(), output: 1 }
        });
    } else if (temp < state.tempLow && state.fan === 1 && !fanReq) {
        state.fan = 0;
        commandMessages.push({
            topic: 'greenhouse/actuator/fan/command',
            payload: { command: 'SET_COIL', coil: 0 }
        });
        commandMessages.push({
            topic: 'greenhouse/climate/command',
            payload: { command_id: Date.now(), output: 0 }
        });
    }
}

// Utility Light Rule: < 30% -> ON; > 40% -> OFF
if (nodeId === 'utility') {
    const light = data.analog;
    if (light < state.lightMin && state.light === 0) {
        state.light = 1;
        commandMessages.push({
            topic: 'greenhouse/actuator/light/command',
            payload: { command: 'SET_COIL', coil: 1 }
        });
        commandMessages.push({
            topic: 'greenhouse/utility/command',
            payload: { command_id: Date.now(), output: 1 }
        });
    } else if (light > state.lightMax && state.light === 1) {
        state.light = 0;
        commandMessages.push({
            topic: 'greenhouse/actuator/light/command',
            payload: { command: 'SET_COIL', coil: 0 }
        });
        commandMessages.push({
            topic: 'greenhouse/utility/command',
            payload: { command_id: Date.now(), output: 0 }
        });
    }
}

flow.set('greenhouse_state', state);
return [commandMessages];

let state = flow.get('greenhouse_state') || {};
const cfg = msg.payload;

if (cfg.auto_mode !== undefined) state.autoMode = cfg.auto_mode;
if (cfg.moisture_a_min !== undefined) state.moistureAMin = cfg.moisture_a_min;
if (cfg.moisture_a_max !== undefined) state.moistureAMax = cfg.moisture_a_max;
if (cfg.moisture_b_min !== undefined) state.moistureBMin = cfg.moisture_b_min;
if (cfg.moisture_b_max !== undefined) state.moistureBMax = cfg.moisture_b_max;
if (cfg.temp_high !== undefined) state.tempHigh = cfg.temp_high;
if (cfg.temp_low !== undefined) state.tempLow = cfg.temp_low;
if (cfg.light_min !== undefined) state.lightMin = cfg.light_min;
if (cfg.light_max !== undefined) state.lightMax = cfg.light_max;

flow.set('greenhouse_state', state);
node.log('Node-RED Gateway thresholds updated from server: ' + JSON.stringify(cfg));
return null;

// Section 5: Slave 1 = Pump, Slave 2 = Fan, Slave 3 = Light
const topic = msg.topic;
const parts = topic.split('/');
const actType = parts[2]; // pump, fan, light
const cmd = msg.payload;

let slaveId = 1;
if (actType === 'fan') slaveId = 2;
if (actType === 'light') slaveId = 3;

const coilVal = cmd.coil !== undefined ? cmd.coil : 0;
const modeVal = cmd.mode !== undefined ? cmd.mode : 1;

// Publish updated feedback state to greenhouse/actuator/<type>/state
const stateMsg = {
    topic: 'greenhouse/actuator/' + actType + '/state',
    payload: {
        slave_id: slaveId,
        type: actType,
        coil: coilVal,
        mode: modeVal,
        target: (actType === 'fan' ? 30 : (actType === 'light' ? 50 : 0)),
        running: coilVal,
        value: coilVal === 1 ? (actType === 'fan' ? 1200 : (actType === 'light' ? 80 : 1)) : 0
    }
};

node.log('Modbus RTU Master: Written Slave ' + slaveId + ' (' + actType + ') Coil 0 = ' + coilVal);
return stateMsg;
